const crypto=require('node:crypto');
const catalogData=require('../data/d3fend-1.6.0.json');
const attack=require('./attack-model');

const MODEL_CONTRACT='shatteredcastles.d3fend.model.v1';
const DEFENSE_CONTRACT='shatteredcastles.d3fend.defense.v1';
const MAP_CONTRACT='shatteredcastles.d3fend.attack-map.v1';
const ALIGNMENT_CONTRACT='shatteredcastles.d3fend.alignment.v1';
const COMPOSITION_CONTRACT='shatteredcastles.d3fend.composition.v1';
const STATUS=['candidate','planned','implemented','observed','unknown','not_implemented'];
const MAPPED_FRAMEWORKS=['enterprise','ics','sparta'];
const SHATTERED_ATTACK_DOMAINS=['enterprise','mobile','ics'];

function stable(v){if(Array.isArray(v))return v.map(stable);if(v&&typeof v==='object')return Object.fromEntries(Object.keys(v).sort().map(k=>[k,stable(v[k])]));return v}
function sha256(v){return crypto.createHash('sha256').update(JSON.stringify(stable(v))).digest('hex')}
function unique(xs){return [...new Set((xs||[]).filter(x=>x!=null&&x!==''))]}
function clean(v){if(v==null||v==='')return null;if(['string','number','boolean'].includes(typeof v))return v;if(Array.isArray(v))return v.map(clean).filter(x=>x!=null);if(typeof v==='object')return Object.fromEntries(Object.entries(v).map(([k,x])=>[k,clean(x)]).filter(([,x])=>x!=null));return String(v)}
function normalizeDomain(raw='enterprise'){const d=String(raw||'enterprise').trim().toLowerCase();if(!SHATTERED_ATTACK_DOMAINS.includes(d))throw new Error(`Unsupported ShatteredCastle ATT&CK domain for D3FEND bridge: ${raw}`);return d}
const BY_ID=new Map(catalogData.techniques.map(x=>[x.id.toLowerCase(),x]));
const BY_NAME=new Map();for(const x of catalogData.techniques){BY_NAME.set(String(x.name||'').toLowerCase(),x);for(const s of x.synonyms||[])BY_NAME.set(String(s).toLowerCase(),x)}
const TACTIC_BY_NAME=new Map(catalogData.tactics.map(x=>[String(x.name).toLowerCase(),x]));
function resolveExact(refs=[]){const resolved=[],unresolved=[];for(const raw of unique(Array.isArray(refs)?refs:[refs])){const key=String(raw).trim().toLowerCase(),x=BY_ID.get(key)||BY_NAME.get(key);if(x)resolved.push({input:raw,record:x});else unresolved.push(raw)}return{resolved,unresolved,selector_policy:'Exact D3FEND ID, exact technique name, or exact published synonym only; no free-text semantic classification.'}}
function model(){
  const body={contract:MODEL_CONTRACT,name:'MITRE D3FEND',version:'1.6.0',released:'2026-08-31',suite:'ShatteredCastle(s)',counts:catalogData.counts,tactics:catalogData.tactics.map(x=>({id:x.id,name:x.name,display_order:x.display_order})),mapping_stats:catalogData.mapping_stats,source:catalogData.source,semantics:{knowledge_graph_of_cybersecurity_countermeasures:true,defensive_techniques_are_not_proof_of_effectiveness:true,exact_selector_only:true,free_text_auto_classification:false,full_mappings_are_inferred_relationships:true,inferred_mapping_is_candidate_not_prescription:true,missing_mapping_is_unknown_not_no_countermeasure:true,automatic_remediation:false,automatic_authorization:false,severity_effect:'none',impact_score_effect:'none'},composition:{attack:{contract:attack.MODEL_CONTRACT,current_version:'v19.2',d3fend_mapping_attack_version:catalogData.source.mapping_attack_version,join:'exact ATT&CK external ID only',mapping_semantics:'D3FEND inferred candidate relationship, not an effectiveness claim'},d3fend:{role:'defensive countermeasure knowledge graph'}}};
  return{...body,model_digest_sha256:sha256(body),catalog_digest_sha256:sha256(catalogData)};
}
function catalog(input={}){const include=String(input.include||'summary').toLowerCase(),body={contract:catalogData.contract,version:catalogData.version,released:catalogData.released,counts:catalogData.counts,source:catalogData.source,mapping_stats:catalogData.mapping_stats};if(include==='all'||include==='tactics')body.tactics=catalogData.tactics;if(include==='all'||include==='techniques')body.techniques=catalogData.techniques;if(include==='all'||include==='families')body.top_level_families=catalogData.techniques.filter(x=>x.top_family_ids.includes(x.id));if(!['summary','all','tactics','techniques','families'].includes(include))throw new Error(`Unsupported D3FEND catalog include: ${include}`);return{...body,catalog_slice_digest_sha256:sha256(body)}}
function resolve(input={}){const r=resolveExact(input.refs||input.selectors||input.ids||[]);return{contract:'shatteredcastles.d3fend.resolve.v1',...r,claim_policy:'Resolution matches exact D3FEND identifiers, names, or published synonyms. It does not infer a countermeasure from prose, telemetry, topology, vulnerability text, or ATT&CK behavior.'}}
function normalizeDefense(input={}){
  const r=resolveExact(input.technique_refs||input.techniques||[]);if(r.unresolved.length)throw new Error(`Unresolved D3FEND selector(s): ${r.unresolved.join(', ')}`);if(!r.resolved.length)throw new Error('D3FEND defense requires at least one explicit defensive technique selector.');const status=String(input.status||'unknown').toLowerCase();if(!STATUS.includes(status))throw new Error(`Unsupported D3FEND defense status: ${status}`);
  const techniques=r.resolved.map(x=>x.record),body={contract:DEFENSE_CONTRACT,defense_id:input.defense_id||input.id||null,status,techniques:techniques.map(x=>({id:x.id,name:x.name,parent_ids:x.parent_ids,top_family_ids:x.top_family_ids,tactics:x.tactics})),tactics:unique(techniques.flatMap(x=>x.tactics)),confidence:clean(input.confidence),evidence_refs:unique(input.evidence_refs||input.evidence||[]),notes:clean(input.notes),semantics:{selectors_explicit_only:true,status_caller_supplied:true,implementation_does_not_imply_effectiveness:true,no_automatic_remediation:true,no_authorization_effect:true,no_severity_effect:true},claim_policy:'A D3FEND defense record preserves explicit defensive-technique selection and caller-supplied implementation status. It does not prove deployment quality, coverage, efficacy, authorization, or risk reduction.'};return{...body,defense_digest_sha256:sha256(body)};
}
function inferredCandidates(domain,attackId){return catalogData.inferred_attack_mappings.filter(x=>x.framework===domain&&x.attack_id===attackId&&x.current_attack_exact_id)}
function mapAttack(input={}){
  const domain=normalizeDomain(input.domain),refs=input.attack_refs||input.technique_refs||input.attack_ids||[],rr=attack.resolveExact(domain,refs,'technique');if(rr.unresolved.length)throw new Error(`Unresolved current ATT&CK selector(s): ${rr.unresolved.join(', ')}`);if(!rr.resolved.length)throw new Error('D3FEND ATT&CK mapping requires at least one explicit current ATT&CK technique selector.');
  const rows=rr.resolved.map(x=>{const rec=x.record,cands=inferredCandidates(domain,rec.id);return{attack_id:rec.id,attack_name:rec.name,attack_version:rec.version,candidates:cands.map(c=>({d3fend_id:c.d3fend_id,d3fend_name:c.d3fend_name,d3fend_tactics:c.d3fend_tactics,top_family_ids:c.top_family_ids,inferred_path_count:c.inferred_path_count,query_techniques:c.query_techniques,defensive_artifact_relations:c.defensive_artifact_relations,defensive_artifacts:c.defensive_artifacts,offensive_artifact_relations:c.offensive_artifact_relations,offensive_artifacts:c.offensive_artifacts})),candidate_count:cands.length,mapping_available:cands.length>0}});
  const body={contract:MAP_CONTRACT,domain,current_attack_model:{contract:attack.MODEL_CONTRACT,version:'v19.2'},d3fend:{contract:MODEL_CONTRACT,version:'1.6.0'},mapping_source:{type:'D3FEND full inferred mappings',d3fend_version:'1.6.0',attack_version:catalogData.source.mapping_attack_version,join_policy:'exact ATT&CK external ID only'},attack_mappings:rows,unmapped_current_attack_ids:rows.filter(x=>!x.mapping_available).map(x=>x.attack_id),semantics:{relationships_are_d3fend_inferred:true,candidates_are_not_prescriptions:true,candidates_are_not_effectiveness_claims:true,missing_mapping_is_unknown_not_no_countermeasure:true,no_automatic_selection:true,no_automatic_remediation:true},claim_policy:'D3FEND ATT&CK mapping returns candidate defensive techniques from D3FEND inferred relationships. A candidate is not a recommendation, implementation claim, or proof that the technique prevents/detects the behavior.'};return{...body,mapping_digest_sha256:sha256(body)};
}
function alignment(input={}){
  const domain=normalizeDomain(input.domain),behaviors=(input.behaviors||[]).map(b=>b?.contract===attack.BEHAVIOR_CONTRACT?b:attack.normalizeBehavior({...b,domain:b.domain||domain}));for(const b of behaviors)if(b.domain!==domain)throw new Error('D3FEND alignment ATT&CK behaviors must use one domain.');const defenses=(input.defenses||[]).map(d=>d?.contract===DEFENSE_CONTRACT?d:normalizeDefense(d));
  const explicit=new Map();for(const d of defenses)for(const t of d.techniques){const arr=explicit.get(t.id)||[];arr.push({defense_id:d.defense_id,status:d.status,evidence_refs:d.evidence_refs});explicit.set(t.id,arr)}
  const attackIds=unique(behaviors.flatMap(b=>b.techniques.map(t=>t.id))),rows=attackIds.map(id=>{const c=inferredCandidates(domain,id),candidateIds=unique(c.map(x=>x.d3fend_id)),overlap=candidateIds.filter(x=>explicit.has(x));return{attack_id:id,inferred_candidate_ids:candidateIds,explicit_defense_overlap:overlap.map(x=>({d3fend_id:x,records:explicit.get(x)})),mapping_available:candidateIds.length>0,explicit_overlap_present:overlap.length>0}});
  const body={contract:ALIGNMENT_CONTRACT,domain,behaviors:behaviors.map(b=>({behavior_id:b.behavior_id,digest:b.behavior_digest_sha256,technique_ids:b.techniques.map(t=>t.id)})),defenses:defenses.map(d=>({defense_id:d.defense_id,digest:d.defense_digest_sha256,status:d.status,technique_ids:d.techniques.map(t=>t.id)})),attack_alignment:rows,unmapped_attack_ids:rows.filter(x=>!x.mapping_available).map(x=>x.attack_id),mapped_without_explicit_defense_overlap:rows.filter(x=>x.mapping_available&&!x.explicit_overlap_present).map(x=>x.attack_id),semantics:{inferred_candidate_overlap_is_not_coverage_proof:true,implemented_status_is_not_effectiveness_proof:true,missing_overlap_is_not_proof_of_no_defense:true,no_weighted_score:true,severity_effect:'none',impact_score_effect:'none'},claim_policy:'Alignment compares explicit defensive records with D3FEND inferred ATT&CK candidates. Overlap is analytical alignment only; it does not establish operational effectiveness or risk reduction.'};return{...body,alignment_digest_sha256:sha256(body)};
}
function compose(input={}){
  const domain=normalizeDomain(input.domain),behaviors=(input.behaviors||[]).map(b=>b?.contract===attack.BEHAVIOR_CONTRACT?b:attack.normalizeBehavior({...b,domain:b.domain||domain})),defenses=(input.defenses||[]).map(d=>d?.contract===DEFENSE_CONTRACT?d:normalizeDefense(d));const behaviorIds=new Set(behaviors.map((b,i)=>String(b.behavior_id||`behavior-${i+1}`)));behaviors.forEach((b,i)=>{if(!b.behavior_id)b.behavior_id=`behavior-${i+1}`});const defenseIds=new Set(defenses.map((d,i)=>String(d.defense_id||`defense-${i+1}`)));defenses.forEach((d,i)=>{if(!d.defense_id)d.defense_id=`defense-${i+1}`});
  const bindings=(input.attack_defense_bindings||input.bindings||[]).map((b,i)=>{const behavior_id=String(b.behavior_id||''),defense_id=String(b.defense_id||'');if(!behaviorIds.has(behavior_id))throw new Error(`D3FEND composition references unknown ATT&CK behavior: ${behavior_id}`);if(!defenseIds.has(defense_id))throw new Error(`D3FEND composition references unknown defense: ${defense_id}`);const behavior=behaviors.find(x=>x.behavior_id===behavior_id),defense=defenses.find(x=>x.defense_id===defense_id),candidatePairs=[];for(const at of behavior.techniques)for(const dt of defense.techniques)if(inferredCandidates(domain,at.id).some(x=>x.d3fend_id===dt.id))candidatePairs.push({attack_id:at.id,d3fend_id:dt.id});const basis=String(b.basis||'analyst').toLowerCase();if(basis==='d3fend_inferred'&&!candidatePairs.length)throw new Error(`D3FEND inferred basis has no exact inferred candidate pair for binding ${i+1}.`);return{binding_id:b.binding_id||`binding-${i+1}`,behavior_id,defense_id,basis,candidate_pairs:candidatePairs,confidence:clean(b.confidence),evidence_refs:unique(b.evidence_refs||[])}});
  const body={contract:COMPOSITION_CONTRACT,domain,behaviors:behaviors.map(b=>({behavior_id:b.behavior_id,digest:b.behavior_digest_sha256,technique_ids:b.techniques.map(t=>t.id)})),defenses:defenses.map(d=>({defense_id:d.defense_id,digest:d.defense_digest_sha256,status:d.status,technique_ids:d.techniques.map(t=>t.id)})),attack_defense_bindings:bindings,semantics:{bindings_explicit_only:true,d3fend_inferred_basis_must_match_catalog:true,analyst_basis_permitted_but_not_recast_as_d3fend_inference:true,no_effectiveness_claim:true,no_automatic_remediation:true},claim_policy:'Composition turns candidate relationships into explicit analyst/operator bindings. Even an exact D3FEND-inferred basis does not prove the selected defense is deployed or effective.'};return{...body,composition_digest_sha256:sha256(body)};
}
function runAction(body={}){const action=String(body.action||'model').toLowerCase();if(action==='model')return model();if(action==='catalog')return catalog(body.input||body);if(action==='resolve')return resolve(body.input||body);if(action==='defense'||action==='normalize_defense')return normalizeDefense(body.defense||body.input||body);if(action==='map_attack'||action==='attack_map')return mapAttack(body.mapping||body.input||body);if(action==='alignment')return alignment(body.alignment||body.input||body);if(action==='compose'||action==='composition')return compose(body.composition||body.input||body);throw new Error(`Unsupported D3FEND action: ${action}`)}
module.exports={MODEL_CONTRACT,DEFENSE_CONTRACT,MAP_CONTRACT,ALIGNMENT_CONTRACT,COMPOSITION_CONTRACT,STATUS,MAPPED_FRAMEWORKS,model,catalog,resolve,resolveExact,normalizeDefense,mapAttack,alignment,compose,runAction,sha256,stable};
